#pragma once

static const char dashboard_html[] = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <title>LumiGrid Factory Dashboard</title>\n    <style>\n        :root {\n            --bg-color: #121212;\n            --surface-color: rgba(255, 255, 255, 0.05);\n            --border-color: rgba(255, 255, 255, 0.1);\n            --accent-color: #bb86fc;\n            --danger-color: #cf6679;\n            --text-color: #e1e1e1;\n            --text-muted: #888;\n            --font-family: 'Inter', -apple-system, BlinkMacSystemFont, \"Segoe UI\", Roboto, sans-serif;\n        }\n\n        body {\n            background-color: var(--bg-color);\n            color: var(--text-color);\n            font-family: var(--font-family);\n            margin: 0;\n            padding: 20px;\n            display: flex;\n            justify-content: center;\n        }\n\n        .container {\n            width: 100%;\n            max-width: 600px;\n            display: flex;\n            flex-direction: column;\n            gap: 20px;\n        }\n\n        h1 {\n            font-size: 24px;\n            margin: 0;\n            text-align: center;\n            font-weight: 600;\n        }\n\n        .card {\n            background: var(--surface-color);\n            border: 1px solid var(--border-color);\n            border-radius: 12px;\n            padding: 20px;\n            backdrop-filter: blur(10px);\n            display: flex;\n            flex-direction: column;\n            gap: 16px;\n        }\n\n        .card-header {\n            font-size: 18px;\n            font-weight: 500;\n            margin: 0;\n            padding-bottom: 12px;\n            border-bottom: 1px solid var(--border-color);\n        }\n\n        label {\n            font-size: 14px;\n            color: var(--text-muted);\n            display: flex;\n            flex-direction: column;\n            gap: 8px;\n        }\n\n        input, select, button {\n            background: rgba(0, 0, 0, 0.2);\n            border: 1px solid var(--border-color);\n            color: var(--text-color);\n            border-radius: 8px;\n            padding: 0 16px;\n            height: 44px; /* Touch target size */\n            font-size: 16px;\n            font-family: var(--font-family);\n            outline: none;\n            transition: all 0.2s;\n        }\n\n        input:focus, select:focus {\n            border-color: var(--accent-color);\n            box-shadow: 0 0 0 2px rgba(187, 134, 252, 0.2);\n        }\n\n        button {\n            cursor: pointer;\n            background: var(--surface-color);\n            font-weight: 500;\n            display: flex;\n            align-items: center;\n            justify-content: center;\n            gap: 8px;\n        }\n\n        button:hover {\n            background: rgba(255, 255, 255, 0.1);\n        }\n\n        button:active {\n            transform: scale(0.98);\n        }\n\n        button.primary {\n            background: var(--accent-color);\n            color: #000;\n            border: none;\n        }\n\n        button.primary:hover {\n            background: #a371f7;\n        }\n\n        button.danger {\n            background: var(--danger-color);\n            color: #000;\n            border: none;\n        }\n\n        button.danger:hover {\n            background: #b55061;\n        }\n\n        .row {\n            display: flex;\n            gap: 12px;\n            align-items: center;\n        }\n\n        .row > * {\n            flex: 1;\n        }\n\n        .status-badge {\n            display: inline-block;\n            padding: 4px 12px;\n            border-radius: 12px;\n            font-size: 12px;\n            font-weight: 600;\n            background: rgba(255, 255, 255, 0.1);\n        }\n\n        .status-badge.active {\n            background: rgba(46, 204, 113, 0.2);\n            color: #2ecc71;\n        }\n\n        .status-badge.error {\n            background: rgba(231, 76, 60, 0.2);\n            color: #e74c3c;\n        }\n\n        .grid-2 {\n            display: grid;\n            grid-template-columns: 1fr 1fr;\n            gap: 12px;\n        }\n\n        #status-json {\n            font-family: monospace;\n            font-size: 12px;\n            background: rgba(0, 0, 0, 0.3);\n            padding: 12px;\n            border-radius: 8px;\n            white-space: pre-wrap;\n            margin: 0;\n        }\n    </style>\n</head>\n<body>\n    <div class=\"container\">\n        <h1>LumiGrid Dashboard</h1>\n\n        <div class=\"card\">\n            <h2 class=\"card-header\">Connection</h2>\n            <label>\n                Base URL\n                <input type=\"text\" id=\"base-url\" value=\"http://lumigrid-factory.local\">\n            </label>\n            <label>\n                Bearer Token\n                <input type=\"password\" id=\"token\" value=\"lumigrid-factory-token-v1\">\n            </label>\n            <div class=\"row\">\n                <button id=\"btn-connect\" class=\"primary\">Connect</button>\n                <span id=\"conn-status\" class=\"status-badge\">Disconnected</span>\n            </div>\n        </div>\n\n        <div class=\"card\">\n            <h2 class=\"card-header\">Device Status</h2>\n            <pre id=\"status-json\">Waiting for connection...</pre>\n            <div class=\"row\">\n                <button id=\"btn-autoloop\">Toggle Auto-Loop</button>\n                <button id=\"btn-abort\" class=\"danger\">Abort (Blackout)</button>\n            </div>\n        </div>\n\n        <div class=\"card\">\n            <h2 class=\"card-header\">Effects</h2>\n            <div class=\"row\">\n                <select id=\"effect-select\">\n                    <option value=\"blackout\">Blackout</option>\n                    <option value=\"identity\">Identity (Lane Colors)</option>\n                    <option value=\"rainbow\">Rainbow</option>\n                    <option value=\"white_walk\">White Walk</option>\n                    <option value=\"pwm_walk\">PWM Walk</option>\n                    <option value=\"pwm_fade\">PWM Fade</option>\n                    <option value=\"combined_pulse\">Combined Pulse</option>\n                    <option value=\"pixel_chase\">Pixel Chase</option>\n                    <option value=\"burn_in\">Burn-In</option>\n                </select>\n                <button id=\"btn-effect\" class=\"primary\">Run Effect</button>\n            </div>\n        </div>\n\n        <div class=\"card\">\n            <h2 class=\"card-header\">Lane Test</h2>\n            <div class=\"grid-2\">\n                <label>Lane (0-7)<input type=\"number\" id=\"lane-idx\" min=\"0\" max=\"7\" value=\"0\"></label>\n                <label>Color (Hex)<input type=\"color\" id=\"lane-color\" value=\"#ff0000\"></label>\n            </div>\n            <button id=\"btn-lane\" class=\"primary\">Test Lane</button>\n        </div>\n\n        <div class=\"card\">\n            <h2 class=\"card-header\">PWM Test</h2>\n            <div class=\"grid-2\">\n                <label>Channel (0-7)<input type=\"number\" id=\"pwm-idx\" min=\"0\" max=\"7\" value=\"0\"></label>\n                <label>Duty (0-4095)<input type=\"number\" id=\"pwm-duty\" min=\"0\" max=\"4095\" value=\"2048\"></label>\n            </div>\n            <button id=\"btn-pwm\" class=\"primary\">Test PWM</button>\n        </div>\n    </div>\n\n    <script>\n        let ws = null;\n        let baseUrl = '';\n        let token = '';\n\n        const el = id => document.getElementById(id);\n        \n        function updateConnStatus(state, isError = false) {\n            const badge = el('conn-status');\n            badge.textContent = state;\n            badge.className = 'status-badge ' + (isError ? 'error' : (state === 'Connected' ? 'active' : ''));\n        }\n\n        async function apiCall(path, method = 'POST', body = null) {\n            try {\n                const res = await fetch(`${baseUrl}/api/v1/factory${path}`, {\n                    method,\n                    headers: {\n                        'Authorization': `Bearer ${token}`,\n                        'Content-Type': 'application/json'\n                    },\n                    body: body ? JSON.stringify(body) : null\n                });\n                if (!res.ok) throw new Error(res.statusText);\n                return await res.json();\n            } catch (err) {\n                console.error('API Error:', err);\n                alert(`API Error: ${err.message}`);\n                throw err;\n            }\n        }\n\n        el('btn-connect').onclick = () => {\n            baseUrl = el('base-url').value.replace(/\\\\/$/, '');\n            token = el('token').value;\n            \n            if (ws) ws.close();\n            \n            updateConnStatus('Connecting...');\n            \n            // Try fetching status via REST first\n            fetch(`${baseUrl}/api/v1/factory/status`, {\n                headers: { 'Authorization': `Bearer ${token}` }\n            })\n            .then(res => res.json())\n            .then(data => {\n                el('status-json').textContent = JSON.stringify(data, null, 2);\n                updateConnStatus('Connected');\n                \n                // Try establishing WebSocket\n                const wsUrl = baseUrl.replace(/^http/, 'ws') + '/ws';\n                ws = new WebSocket(wsUrl);\n                ws.onmessage = e => {\n                    try {\n                        const state = JSON.parse(e.data);\n                        el('status-json').textContent = JSON.stringify(state, null, 2);\n                    } catch (err) {}\n                };\n                ws.onclose = () => {\n                    updateConnStatus('WS Closed - Polling');\n                    // Fallback to polling if WS closes\n                    setInterval(() => {\n                        if (ws && ws.readyState === WebSocket.OPEN) return;\n                        fetch(`${baseUrl}/api/v1/factory/status`, {\n                            headers: { 'Authorization': `Bearer ${token}` }\n                        }).then(r => r.json()).then(d => {\n                            el('status-json').textContent = JSON.stringify(d, null, 2);\n                        }).catch(e => {});\n                    }, 1000);\n                };\n            })\n            .catch(err => {\n                updateConnStatus('Connection Failed', true);\n            });\n        };\n\n        el('btn-abort').onclick = () => apiCall('/abort');\n        \n        el('btn-autoloop').onclick = () => {\n            // Read current JSON to see if loop is enabled\n            try {\n                const state = JSON.parse(el('status-json').textContent);\n                apiCall('/auto-loop', 'POST', { enabled: !state.autoLoop });\n            } catch (e) {\n                apiCall('/auto-loop', 'POST', { enabled: true });\n            }\n        };\n\n        el('btn-effect').onclick = () => {\n            apiCall('/effect', 'POST', {\n                effect: el('effect-select').value,\n                durationMs: 5000\n            });\n        };\n\n        el('btn-lane').onclick = () => {\n            const hex = el('lane-color').value;\n            apiCall('/lane', 'POST', {\n                lane: parseInt(el('lane-idx').value),\n                red: parseInt(hex.substr(1,2), 16),\n                green: parseInt(hex.substr(3,2), 16),\n                blue: parseInt(hex.substr(5,2), 16),\n                brightness: 64,\n                durationMs: 5000\n            });\n        };\n\n        el('btn-pwm').onclick = () => {\n            apiCall('/pwm', 'POST', {\n                channel: parseInt(el('pwm-idx').value),\n                duty: parseInt(el('pwm-duty').value),\n                durationMs: 2000\n            });\n        };\n    </script>\n</body>\n</html>\n";
